//! The symbol and emoji catalog of the 符號與 Emoji 面板: categories, search and the recent list.
//!
//! The catalog is `data/symbols.tsv`, generated by `generate.py` from Unicode CLDR annotations (zh-Hant, zh-Hant-HK,
//! en) and Unicode emoji-test.txt (Unicode License v3), with the Zhuyin readings of the Chinese keywords taken from
//! the app's lexicon.  It is built into the library and parsed once.
//!
//! A search query is what the user typed in the picker: Chinese text (a prefilled composition), Zhuyin symbols, or
//! raw keys of the standard Zhuyin layout, which are read both as Zhuyin (tones optional) and as English.

use std::collections::HashMap;
use std::sync::OnceLock;

use zhuyin_core::keyboard;

const DATA: &str = include_str!("../data/symbols.tsv");

/// The most symbols the recent list keeps.
pub const RECENT_CAPACITY: usize = 32;
/// The recent list's file name in the app's own data directory.
pub const RECENT_FILE: &str = "recent-symbols.txt";

/// One symbol or emoji.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Symbol {
    /// What is inserted.
    pub text: String,
    /// The Traditional Chinese name (CLDR), or a short English name when CLDR has none.
    pub name: String,
}

/// A category of the picker, in display order.
#[derive(Clone, Debug)]
pub struct Category {
    /// `punctuation`, `brackets`, … `smileys`, … `flags`.
    pub id: &'static str,
    /// 常用標點, 括號, …
    pub title: &'static str,
    /// The category's symbols, in order.
    pub symbols: Vec<Symbol>,
}

/// What a symbol is found by.
struct Keys {
    category: usize,
    index: usize,
    chinese: Vec<&'static str>,
    /// Toneless syllables of each Chinese keyword.
    readings: Vec<Vec<&'static str>>,
    english: Vec<&'static str>,
}

struct Catalog {
    categories: Vec<Category>,
    keys: Vec<Keys>,
    names: HashMap<&'static str, (usize, usize)>,
}

fn catalog() -> &'static Catalog {
    static CATALOG: OnceLock<Catalog> = OnceLock::new();
    CATALOG.get_or_init(|| parse(DATA))
}

fn parse(data: &'static str) -> Catalog {
    let mut categories: Vec<Category> = Vec::new();
    let mut keys = Vec::new();
    let mut names = HashMap::new();
    for line in data.lines() {
        if line.starts_with("##") || line.is_empty() {
            continue;
        }
        let fields: Vec<&'static str> = line.split('\t').collect();
        if fields[0] == "#category" {
            categories.push(Category { id: fields[1], title: fields[2], symbols: Vec::new() });
            continue;
        }
        let Some(category) = categories.last() else { continue };
        let field = |i: usize| fields.get(i).copied().unwrap_or("");
        let list = |text: &'static str| text.split('|').filter(|part| !part.is_empty()).collect::<Vec<_>>();
        let index = category.symbols.len();
        let position = (categories.len() - 1, index);
        names.entry(field(0)).or_insert(position);
        keys.push(Keys {
            category: position.0,
            index,
            chinese: list(field(2)),
            readings: list(field(3)).into_iter().map(|reading| reading.split(' ').collect()).collect(),
            english: list(field(4)),
        });
        let category = categories.last_mut().expect("a category");
        category.symbols.push(Symbol { text: field(0).to_owned(), name: field(1).to_owned() });
    }
    Catalog { categories, keys, names }
}

/// Every category of the catalog, in display order (最近使用 is the platform's).
#[must_use]
pub fn categories() -> &'static [Category] {
    &catalog().categories
}

/// The name of a symbol in the catalog, for recent items (with or without U+FE0F).
#[must_use]
pub fn name_of(text: &str) -> Option<&'static str> {
    let catalog = catalog();
    let position = catalog.names.get(text).or_else(|| {
        let bare = text.replace('\u{fe0f}', "");
        catalog.names.get(bare.as_str()).or_else(|| catalog.names.get(format!("{bare}\u{fe0f}").as_str()))
    })?;
    Some(catalog.categories[position.0].symbols[position.1].name.as_str())
}

/// Zhuyin syllables (with their tone marks) from raw standard-layout keys, or `None` when a key is not a Zhuyin or
/// tone key.  Space ends a syllable.
fn decode_keys(keys: &str) -> Option<Vec<String>> {
    let mut symbols = String::new();
    for key in keys.chars() {
        let key = key.to_ascii_lowercase();
        if key == ' ' {
            symbols.push(' ');
        } else if let Some(mark) = keyboard::tone(key) {
            symbols.push_str(mark);
        } else {
            symbols.push(keyboard::symbol(key)?);
        }
    }
    syllables(&symbols)
}

/// Zhuyin text split into syllables: a tone mark or space ends one, and a symbol that cannot follow the previous
/// one (an initial after a medial, …) starts the next.  `None` when the text has anything but Zhuyin.
fn syllables(text: &str) -> Option<Vec<String>> {
    let mut result: Vec<String> = Vec::new();
    let mut current = String::new();
    let mut last_slot: Option<usize> = None;
    for c in text.chars() {
        if c == ' ' || keyboard::is_tone_mark(c) || c == 'ˉ' {
            if !current.is_empty() {
                if c != ' ' {
                    current.push(c);
                }
                result.push(std::mem::take(&mut current));
            }
            last_slot = None;
            continue;
        }
        let slot = keyboard::slot(c)?;
        if last_slot.is_some_and(|last| slot <= last) {
            result.push(std::mem::take(&mut current));
        }
        current.push(c);
        last_slot = Some(slot);
    }
    if !current.is_empty() {
        result.push(current);
    }
    (!result.is_empty()).then_some(result)
}

fn toneless(syllable: &str) -> String {
    syllable.chars().filter(|&c| !keyboard::is_tone_mark(c) && c != 'ˉ').collect()
}

/// How the query is shown in the picker: Zhuyin when raw keys decode, otherwise the text as typed.
#[must_use]
pub fn display_query(query: &str) -> String {
    if query.is_ascii()
        && let Some(syllables) = decode_keys(query)
    {
        return syllables.concat();
    }
    query.to_owned()
}

fn chinese_score(keys: &Keys, name: &str, query: &str) -> u32 {
    let mut best = 0;
    if name == query {
        best = 105;
    } else if name.contains(query) {
        // A tie on a keyword goes to the symbol whose name has the query: 台灣 → 🇹🇼 before 🧋.
        best = 3;
    }
    for keyword in &keys.chinese {
        let score = if *keyword == query {
            100
        } else if keyword.starts_with(query) {
            80
        } else if keyword.contains(query) {
            60
        } else {
            0
        };
        best = best.max(score);
    }
    if best > 3 && name.contains(query) { best + 3 } else { best }
}

fn zhuyin_score(keys: &Keys, query: &[String]) -> u32 {
    let (last, whole) = query.split_last().expect("a syllable");
    let mut best = 0;
    for reading in &keys.readings {
        for offset in 0..reading.len() {
            let rest = &reading[offset..];
            if rest.len() < query.len()
                || !whole.iter().zip(rest).all(|(typed, syllable)| typed == syllable)
                || !rest[whole.len()].starts_with(last.as_str())
            {
                continue;
            }
            let exact_last = rest[whole.len()] == last.as_str();
            let score = match (offset, rest.len() == query.len(), exact_last) {
                (0, true, true) => 95,
                (0, true, false) => 75,
                (0, false, _) => 70,
                (_, _, true) => 55,
                _ => 45,
            };
            best = best.max(score);
        }
    }
    best
}

fn english_score(keys: &Keys, query: &str) -> u32 {
    let mut best = 0;
    for keyword in &keys.english {
        let score = if *keyword == query {
            90
        } else if keyword.split([' ', ':', ',', '-']).any(|word| word == query) {
            85
        } else if query.len() >= 2 && keyword.starts_with(query) {
            65
        } else if query.len() >= 2 && keyword.split([' ', '-']).any(|word| word.starts_with(query)) {
            60
        } else {
            0
        };
        best = best.max(score);
    }
    // A tie goes to the shortest name with the word: "heart" → ❤️ (red heart) before 💘 (heart with arrow).
    if let Some(name) = keys.english.first()
        && best > 0
        && name.split(' ').any(|word| word == query)
    {
        best += 4 - (name.split(' ').count() as u32 - 1).min(3);
    }
    best
}

/// The symbols matching `query`, best first (then in catalog order), at most `limit`; none for an empty query.
#[must_use]
pub fn search(query: &str, limit: usize) -> Vec<&'static Symbol> {
    let query = query.trim();
    if query.is_empty() || limit == 0 {
        return Vec::new();
    }
    let catalog = catalog();
    let ascii = query.is_ascii();
    let zhuyin: Option<Vec<String>> = if ascii { decode_keys(query) } else { syllables(query) }
        .map(|syllables| syllables.iter().map(|syllable| toneless(syllable)).collect());
    let zhuyin = zhuyin.filter(|syllables: &Vec<String>| syllables.iter().all(|syllable| !syllable.is_empty()));
    let english = ascii.then(|| query.to_ascii_lowercase());
    let mut found: Vec<(u32, usize)> = Vec::new();
    for (order, keys) in catalog.keys.iter().enumerate() {
        let symbol = &catalog.categories[keys.category].symbols[keys.index];
        let mut score = if symbol.text == query || symbol.text.replace('\u{fe0f}', "") == query {
            110
        } else if ascii {
            0
        } else {
            chinese_score(keys, &symbol.name, query)
        };
        if let Some(syllables) = &zhuyin {
            score = score.max(zhuyin_score(keys, syllables));
        }
        if let Some(english) = &english {
            score = score.max(english_score(keys, english));
        }
        if score > 0 {
            found.push((score, order));
        }
    }
    found.sort_by_key(|&(score, order)| (std::cmp::Reverse(score), order));
    let mut seen = std::collections::HashSet::new();
    found
        .into_iter()
        .map(|(_, order)| {
            let keys = &catalog.keys[order];
            &catalog.categories[keys.category].symbols[keys.index]
        })
        .filter(|symbol| seen.insert(symbol.text.as_str()))
        .take(limit)
        .collect()
}

/// The recently inserted symbols, newest first, at most [`RECENT_CAPACITY`].
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Recent {
    items: Vec<String>,
}

impl Recent {
    /// The list stored by [`Recent::to_text`]; blank lines and repeats are dropped.
    #[must_use]
    pub fn from_text(text: &str) -> Recent {
        let mut recent = Recent::default();
        for line in text.lines().map(str::trim).filter(|line| !line.is_empty()) {
            if recent.items.len() < RECENT_CAPACITY && !recent.items.iter().any(|item| item == line) {
                recent.items.push(line.to_owned());
            }
        }
        recent
    }

    /// One symbol per line, newest first.
    #[must_use]
    pub fn to_text(&self) -> String {
        let mut text = String::new();
        for item in &self.items {
            text.push_str(item);
            text.push('\n');
        }
        text
    }

    /// Puts `symbol` first, removing an earlier copy and the oldest beyond the capacity.
    pub fn push(&mut self, symbol: &str) {
        let symbol = symbol.trim();
        if symbol.is_empty() || symbol.contains('\n') {
            return;
        }
        self.items.retain(|item| item != symbol);
        self.items.insert(0, symbol.to_owned());
        self.items.truncate(RECENT_CAPACITY);
    }

    /// The symbols, newest first.
    #[must_use]
    pub fn items(&self) -> &[String] {
        &self.items
    }

    /// Forgets every symbol.
    pub fn clear(&mut self) {
        self.items.clear();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn texts(query: &str, limit: usize) -> Vec<&'static str> {
        search(query, limit).into_iter().map(|symbol| symbol.text.as_str()).collect()
    }

    #[test]
    fn categories_load_in_order() {
        let ids: Vec<_> = categories().iter().map(|category| category.id).collect();
        assert_eq!(
            ids,
            [
                "punctuation",
                "brackets",
                "math",
                "arrows",
                "units",
                "bopomofo",
                "greek",
                "box",
                "smileys",
                "people",
                "animals",
                "food",
                "travel",
                "activities",
                "objects",
                "symbols",
                "flags"
            ]
        );
        assert!(categories().iter().all(|category| !category.symbols.is_empty()));
        assert_eq!(categories()[0].symbols[0], Symbol { text: "，".into(), name: "逗號".into() });
        let emoji: usize = categories()[8..].iter().map(|category| category.symbols.len()).sum();
        assert!(emoji > 1800, "{emoji} emoji");
    }

    #[test]
    fn names_of_recent_items() {
        assert_eq!(name_of("❤️"), Some("愛心"));
        assert_eq!(name_of("❤"), Some("愛心"));
        assert_eq!(name_of("🇹🇼"), Some("旗子：台灣"));
        assert_eq!(name_of("not a symbol"), None);
    }

    #[test]
    fn chinese_search_ranks_exact_names_first() {
        assert_eq!(texts("愛心", 1), ["❤️"]);
        let laughing = texts("笑", 30);
        assert!(laughing.contains(&"😂") && laughing.contains(&"😄"), "{laughing:?}");
        assert_eq!(texts("逗號", 1), ["，"]);
        assert_eq!(texts("台灣", 1), ["🇹🇼"]);
    }

    #[test]
    fn zhuyin_keys_search_without_tones() {
        // ㄞ ㄒㄧㄣ (愛心) typed as standard-layout keys, tones left out.
        assert_eq!(display_query("9vup"), "ㄞㄒㄧㄣ");
        assert_eq!(texts("9vup", 1), ["❤️"]);
        // ㄒㄧㄠ (笑) also matches inside 大笑.
        let laughing = texts("vul", 200);
        assert!(laughing.contains(&"😂"), "{laughing:?}");
        // Tone keys are accepted and ignored.
        assert_eq!(texts("9vup", 3), texts("94vup", 3));
        // Zhuyin text works the same.
        assert_eq!(texts("ㄞˋㄒㄧㄣ", 1), ["❤️"]);
    }

    #[test]
    fn english_search() {
        let hearts = texts("heart", 30);
        assert!(hearts.contains(&"❤️"), "{hearts:?}");
        assert_eq!(texts("taiwan", 1), ["🇹🇼"]);
        assert!(texts("", 10).is_empty());
        assert!(texts("zzzzqqqq", 10).is_empty());
    }

    #[test]
    fn display_keeps_text_that_is_not_keys() {
        assert_eq!(display_query("笑"), "笑");
        assert_eq!(display_query("vul4"), "ㄒㄧㄠˋ");
        assert_eq!(display_query("Hi!"), "Hi!");
    }

    #[test]
    fn recent_list() {
        let mut recent = Recent::from_text("😀\n\n，\n😀\n");
        assert_eq!(recent.items(), ["😀", "，"]);
        recent.push("，");
        assert_eq!(recent.items(), ["，", "😀"]);
        recent.push("");
        recent.push("a\nb");
        assert_eq!(recent.to_text(), "，\n😀\n");
        for i in 0..40 {
            recent.push(&i.to_string());
        }
        assert_eq!(recent.items().len(), RECENT_CAPACITY);
        assert_eq!(recent.items()[0], "39");
        assert_eq!(Recent::from_text(&recent.to_text()), recent);
        recent.clear();
        assert!(recent.items().is_empty());
    }
}
